function ServiceWorkerRefresh(){useEffect(()=>{if(!('serviceWorker'in navigator))return; navigator.serviceWorker.register('/sw.js?v=21',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{})},[]);return null}
