type Status='not_started'|'in_progress'|'completed'|'skipped'; type Priority='low'|'medium'|'high';
type Subject={id:string;name:string;color:string;priority:Priority}; type Unit={id:string;subjectId:string;name:string};
type Lesson={id:string;unitId:string;name:string;estimatedMinutes:number;status:Status;priority:Priority;lastReviewedAt?:string;nextReviewAt?:string};
type Task={id:string;lessonId:string;date:string;estimatedMinutes:number;status:Status;priority:Priority;startTime?:string};
type ClassSlot={id:string;title:string;dayOfWeek:number;startTime:string;endTime:string;subjectId?:string;notes?:string}; type StudyScheduleSlot={id:string;date:string;subjectId:string;duration:number};
type Session={id:string;date:string;subjectId:string;lessonId?:string;duration:number;type:'focus'|'review';startedAt?:string};
type Lecture={id:string;title:string;subjectId:string;unitId?:string;lessonId?:string;kind:'book'|'pdf'|'lecture'|'link'|'notes'|'other';description:string;url?:string;fileName?:string;size?:number;createdAt:string;favorite:boolean};
type Question={id:string;subjectId:string;lessonId?:string;question:string;answer:string;difficulty:'easy'|'medium'|'hard';type:'mcq'|'tf'|'written'};
type Mistake={id:string;questionId?:string;subjectId:string;question:string;reason:string;correctAnswer:string;notes:string;status?:'needs_review'|'fixed'}; type Note={id:string;subjectId:string;lessonId?:string;title:string;content:string;updatedAt:string};
type Settings={navOrder?:string[];theme:'dark'|'light'|'system';language:'ar'|'en';dailyStudyMinutes:number;restDays:number[];notificationTime:string;startTime:string;sessionMinutes:number;minDailyMinutes:number;dailyTasks:number;focus:number;break:number;morning:boolean;study:boolean;overdue:boolean;review:boolean;endDay:boolean};
type SiteAnnouncement={id:string;title:string;message:string;type:'first'|'fixed'|'temporary';placement:'top'|'center'|'modal';durationSec:number;buttonText:string;buttonUrl:string;expiresAt:number|null};
type GlobalNotification={id:string;title:string;message:string;type:'info'|'success'|'warning'|'urgent';expiresAt:number|null;createdAt:number};
type Store={profile:{name:string;grade:string;section:string;school:string;goal:string;whatsapp?:string};subjects:Subject[];units:Unit[];lessons:Lesson[];tasks:Task[];sessions:Session[];questions:Question[];mistakes:Mistake[];notes:Note[];lectures:Lecture[];trashLectures:Lecture[];classSchedule:ClassSlot[];studySchedule:StudyScheduleSlot[];xp:number;challengeClaims:string[];settings:Settings;onboarded:boolean;onboardStep:number;planStart:string;planEnd:string;sentNotifications:string[]};
const KEY='thanaweya-os-v3',id=()=>crypto.randomUUID(),today=()=>new Date().toISOString().slice(0,10);
const initial:Store={profile:{name:'',grade:'الصف الثالث الثانوي',section:'',school:'',goal:'',whatsapp:''},subjects:[],units:[],lessons:[],tasks:[],sessions:[],questions:[],mistakes:[],notes:[],lectures:[],trashLectures:[],classSchedule:[],studySchedule:[],xp:0,challengeClaims:[],onboarded:false,onboardStep:1,planStart:today(),planEnd:'',sentNotifications:[],settings:{navOrder:['home','focus','schedule','curriculum','plan','tasks','review','questions','mistakes','notes','lectures','mission','dna','memory','time','rpg','calendar','stats','achievements','settings'],theme:'dark',language:'ar',dailyStudyMinutes:180,restDays:[5],notificationTime:'19:00',startTime:'17:00',sessionMinutes:45,minDailyMinutes:30,dailyTasks:3,focus:25,break:5,morning:true,study:true,overdue:true,review:true,endDay:true}};
function clean(v:string){return v.replace(/[<>]/g,'').trim().slice(0,500)}
function validPersonName(v:string){return /^[\p{L}]+(?:[\p{L}.'-]*)(?:\s+[\p{L}]+(?:[\p{L}.'-]*))*$/u.test(v.trim())}
function validUrl(v:string){try{const u=new URL(v.trim());return u.protocol==='http:'||u.protocol==='https:'}catch{return false}}
function fieldError(msg:string){return <p className="fieldError" role="alert">⚠️ {msg}</p>}
function load():Store{try{const x=JSON.parse(localStorage.getItem(KEY)||'null');return x?({...initial,...x,notes:Array.isArray(x.notes)?x.notes:[],lectures:Array.isArray(x.lectures)?x.lectures:[],trashLectures:Array.isArray(x.trashLectures)?x.trashLectures:[],classSchedule:Array.isArray(x.classSchedule)?x.classSchedule:[],studySchedule:Array.isArray(x.studySchedule)?x.studySchedule:[],challengeClaims:Array.isArray(x.challengeClaims)?x.challengeClaims:[],settings:{...initial.settings,...x.settings}}):initial}catch{return initial}}
function addDays(ds:string,n:number){const d=new Date(ds);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function priority(t:Task){return(t.date<today()?100:0)+(t.priority==='high'?30:t.priority==='medium'?20:10)}
function calcStreak(s:Store){let n=0,d=new Date();for(;;){const ds=d.toISOString().slice(0,10),m=s.sessions.filter(x=>x.date===ds).reduce((a,x)=>a+x.duration,0);if(m<s.settings.minDailyMinutes)break;n++;d.setDate(d.getDate()-1);if(n>366)break}return n}
function longestStreak(s:Store){const days=[...new Set(s.sessions.map(x=>x.date))].sort();let best=0,run=0,prev='';for(const d of days){const ok=!prev||d===addDays(prev,1);run=ok?run+1:1;best=Math.max(best,run);prev=d}return best}
