const englishOriginalText=new WeakMap<Text,string>();
const englishOriginalAttrs=new WeakMap<HTMLElement,Record<string,string|null>>();

function applyEnglish(root:HTMLElement,enabled:boolean){
 const dict={...EN,...EN_MORE};
 const replace=(value:string)=>{let out=value;for(const [ar,en] of Object.entries(dict).sort((a,b)=>b[0].length-a[0].length)){if(out.includes(ar))out=out.split(ar).join(en)}return out;};
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 const textNodes:Text[]=[];
 while(walker.nextNode())textNodes.push(walker.currentNode as Text);
 if(enabled){
   for(const node of textNodes){
     const raw=node.nodeValue||'';
     if(!raw.trim())continue;
     if(!englishOriginalText.has(node))englishOriginalText.set(node,raw);
     node.nodeValue=replace(englishOriginalText.get(node)||raw);
   }
 }else{
   for(const node of textNodes){
     const original=englishOriginalText.get(node);
     if(original!==undefined)node.nodeValue=original;
   }
 }
 root.querySelectorAll<HTMLElement>("[placeholder],[aria-label],[title],[alt]").forEach(el=>{
   const attrs=["placeholder","aria-label","title","alt"];
   if(enabled){
     if(!englishOriginalAttrs.has(el)){
       const saved:Record<string,string|null>={};
       for(const a of attrs)saved[a]=el.getAttribute(a);
       englishOriginalAttrs.set(el,saved);
     }
     for(const a of attrs){const v=englishOriginalAttrs.get(el)?.[a];if(v)el.setAttribute(a,replace(v));}
   }else{
     const saved=englishOriginalAttrs.get(el);
     if(saved)for(const a of attrs){const v=saved[a];if(v===null)el.removeAttribute(a);else el.setAttribute(a,v);}
   }
 });
}

const LECTURE_DB='thanaweya-lecture-files';
function lectureDB(){return new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open(LECTURE_DB,1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function saveLectureFile(key:string,file:File){const db=await lectureDB();return new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function getLectureFile(key:string){try{const db=await lectureDB();const file=await new Promise<Blob|null>((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)});db.close();return file}catch{return null}}
async function openLectureFile(key:string){const file=await getLectureFile(key);if(file)window.open(URL.createObjectURL(file),'_blank','noopener')}
async function downloadLectureFile(key:string,name:string){const file=await getLectureFile(key);if(!file)return;const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=name||'thanaweya-file';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function deleteLectureFile(key:string){try{const db=await lectureDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close()}catch{}}

function getVideoEmbedUrl(raw:string){
 try{
  const u=new URL(raw.trim());
  if(!/^https?:$/.test(u.protocol))return null;
  const host=u.hostname.toLowerCase().replace(/^www\./,'');
  if(host==='youtube.com'||host==='m.youtube.com'||host==='youtube-nocookie.com'){
   const v=u.searchParams.get('v');
   if(v)return 'https://www.youtube.com/embed/'+encodeURIComponent(v)+'?rel=0';
   const m=u.pathname.match(/^\/(?:shorts|embed)\/([^/?#]+)/);
   if(m)return 'https://www.youtube.com/embed/'+encodeURIComponent(m[1])+'?rel=0';
  }
  if(host==='youtu.be'){
   const v=u.pathname.split('/').filter(Boolean)[0];
   if(v)return 'https://www.youtube.com/embed/'+encodeURIComponent(v)+'?rel=0';
  }
  if(host==='vimeo.com'||host==='player.vimeo.com'){
   const m=u.pathname.match(/\/(?:video\/)?(\d+)/);
   if(m)return 'https://player.vimeo.com/video/'+m[1];
  }
  if(host==='dailymotion.com'||host==='dai.ly'){
   const m=u.pathname.match(/(?:video\/|\/)([A-Za-z0-9]+)/);
   if(m)return 'https://www.dailymotion.com/embed/video/'+m[1];
  }
  if(host==='twitch.tv'){
   const v=u.pathname.match(/\/videos\/(\d+)/);
   if(v)return 'https://player.twitch.tv/?video='+v[1]+'&parent='+encodeURIComponent(location.hostname||'localhost');
  }
  if(/\.(mp4|webm|ogg)(?:$|[?#])/i.test(u.pathname))return u.href;
  return null;
 }catch{return null}
}
